import os
import json
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _shape_bounding_box(geometry: Dict[str, Any]) -> Optional[Dict[str, float]]:
    bbox = geometry.get("BoundingBox") or {}
    if not bbox:
        return None
    return {
        "left": float(bbox.get("Left", 0.0)),
        "top": float(bbox.get("Top", 0.0)),
        "width": float(bbox.get("Width", 0.0)),
        "height": float(bbox.get("Height", 0.0)),
    }


def _polygon_to_points(geometry: Dict[str, Any]) -> List[Dict[str, float]]:
    poly = geometry.get("Polygon") or []
    points = []
    for p in poly:
        points.append({"x": float(p.get("X", 0.0)), "y": float(p.get("Y", 0.0))})
    return points


def _extract_text(blocks_by_id: Dict[str, Dict[str, Any]], block: Dict[str, Any]) -> str:
    text = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") != "CHILD":
            continue
        for child_id in rel.get("Ids", []):
            child = blocks_by_id.get(child_id)
            if not child:
                continue
            if child.get("BlockType") == "WORD":
                text.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    text.append("X")
    return " ".join(t for t in text if t).strip()


def _extract_table_structure(blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    blocks_by_id = {b.get("Id"): b for b in blocks if b.get("Id")}
    tables = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        cells = []
        row_map: Dict[int, Dict[int, Dict[str, Any]]] = {}

        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for child_id in rel.get("Ids", []):
                child = blocks_by_id.get(child_id)
                if not child or child.get("BlockType") != "CELL":
                    continue

                row_index = int(child.get("RowIndex", 0) or 0)
                col_index = int(child.get("ColumnIndex", 0) or 0)
                row_span = int(child.get("RowSpan", 1) or 1)
                col_span = int(child.get("ColumnSpan", 1) or 1)

                cell = {
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": row_span,
                    "column_span": col_span,
                    "text": _extract_text(blocks_by_id, child),
                    "confidence": float(child.get("Confidence", 0.0) or 0.0),
                    "bbox": _shape_bounding_box(child.get("Geometry", {})),
                    "polygon": _polygon_to_points(child.get("Geometry", {})),
                }
                cells.append(cell)
                row_map.setdefault(row_index, {})[col_index] = cell

        rows = []
        for row_index in sorted(row_map.keys()):
            cols = row_map[row_index]
            max_col = max(cols.keys()) if cols else 0
            row_cells = []
            for col_index in range(1, max_col + 1):
                row_cells.append(cols.get(col_index))
            rows.append({"row_index": row_index, "cells": row_cells})

        tables.append(
            {
                "confidence": float(block.get("Confidence", 0.0) or 0.0),
                "bbox": _shape_bounding_box(block.get("Geometry", {})),
                "polygon": _polygon_to_points(block.get("Geometry", {})),
                "cells": sorted(cells, key=lambda c: (c["row_index"], c["column_index"])),
                "rows": rows,
            }
        )

    return tables


def extract_table_cells_and_rows(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Extracts table cells and row structure from a document using Amazon Textract.

    Requires:
      - AWS_ACCESS_KEY_ID
      - AWS_SECRET_ACCESS_KEY
      - Optional: AWS_DEFAULT_REGION (default: us-east-1)
    """
    region = os.getenv("AWS_DEFAULT_REGION", "us-east-1")
    textract = boto3.client("textract", region_name=region)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract analyze_document failed: {e}") from e

    blocks = response.get("Blocks", [])
    tables = _extract_table_structure(blocks)

    return {
        "provider": "amazon_textract",
        "document_metadata": response.get("DocumentMetadata", {}),
        "job_status": response.get("JobStatus", "SUCCEEDED"),
        "tables": tables,
        "raw_response": response,
    }


def extract_table_cells_and_rows_from_path(file_path: str) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        data = f.read()
    return extract_table_cells_and_rows(data)


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <document_path>")
    result = extract_table_cells_and_rows_from_path(sys.argv[1])
    print(json.dumps(result, indent=2, ensure_ascii=False))
